#include <iostream>
#include <iomanip>

int main() {
    char chars[] = {'A', 'a', '0', ' '};

    for (char c : chars) {
        unsigned char uc = static_cast<unsigned char>(c);
        int dec = static_cast<int>(uc);
        int row_dec = dec / 10;
        int col_dec = dec % 10;
        int row_hex = dec / 16;
        int col_hex = dec % 16;

        std::cout << "Char '" << c << "' -> Dec: " << dec
                  << " (Row " << row_dec << ", Col " << col_dec << ")"
                  << " | Hex: 0x" << std::hex << std::uppercase << dec << std::dec
                  << " (Row " << row_hex << ", Col " << std::hex << std::uppercase << col_hex << std::dec << ")\n";
    }
    return 0;
}

#include <iostream>

int main() {
    int a = 10, b = 20, c = 5;

    // Multiplicative vs Additive
    int r1 = a + b * c;         // 10 + (20 * 5) = 110

    // Shift vs Additive
    int r2 = 1 << 2 + 1;        // 1 << (2 + 1) = 8
    int r3 = (1 << 2) + 1;      // (4) + 1 = 5

    // Bitwise AND vs Equality
    int val = 4;
    bool check1 = val & 1 == 0;   // val & (1 == 0) -> 4 & 0 -> false (0)
    bool check2 = (val & 1) == 0; // (4 & 1) == 0 -> 0 == 0 -> true (1)

    // Right-to-left assignment
    int x, y, z;
    x = y = z = 42;

    std::cout << "r1: " << r1 << "\n";
    std::cout << "r2: " << r2 << "\n";
    std::cout << "r3: " << r3 << "\n";
    std::cout << "check1: " << check1 << "\n";
    std::cout << "check2: " << check2 << "\n";
    std::cout << "x, y, z: " << x << ", " << y << ", " << z << "\n";

    return 0;
}
